class CItpSpSequenceNumber(TextualConvention, Unsigned32):
    description = 'This textual convention defines all of the allowed\n                 values for a sequence of integers used by the \n                 SS7 protocol to transmit and acknowledge packets.\n                 The range is specified from 0 to maximum allowed \n                 value for extended sequence numbers.  The actual \n                 range will depend on the type of link and   \n                 the variant.  The value will increase and then wrap\n                 to the zero value. The following are examples of \n                 valid sequences.\n                 0..126,127,0..\n                 0..254,255,0..\n                 0..32766,32767,0..\n                 0..65534,65535,0..'
    status = 'deprecated'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(0, 65535)

class CItpSpSampleInterval(TextualConvention, Unsigned32):
    description = 'This textual convention defines the allowed values\n                 for a sample interval.  This value is specified in\n                 seconds and ranges from 1 minute to 1 hour.'
    status = 'deprecated'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(60, 3600)

class CItpSpPercentThreshold(TextualConvention, Unsigned32):
    description = 'This textual convention defines the allowed values\n                 for a thresholds specified as percentage of \n                 link utilization.  A value of zero indicates that\n                 this specific threshold is to be ignored.'
    status = 'deprecated'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(0, 100)

class CItpSpLinkUtilization(TextualConvention, Unsigned32):
    description = 'This textual convention defines a range of \n                 percentages that represent the utilization of \n                 a link. Any value over 999 will be represented\n                 as 999.\n                 \n                 For SS7 links based on IP/SCTP the link capacity \n                 is not directly related to the interface speed used\n                 to transmit packets.  This is different from serial\n                 and HSL links.  The capacity of these types of \n                 links depend on the amount of resources available\n                 in the IP cloud.  The IP cloud must be provisioned\n                 to support traffic for all SS7 links. In order to \n                 monitor link utilization on IP/SCTP based SS7 links\n                 a planned capacity must be specified.  If this value\n                 is incorrectly estimated or traffic exceeds this \n                 expected value link utilization may exceed 100\n                 percent.  This is possible because the IP cloud\n                 may be provisioned with additional capacity or \n                 may discard less important traffic based on Qos\n                 parameters.\n                 \n                 When a SS7 link has not be configured for link \n                 utilization monitoring this value object will\n                 have a value of zero.'
    status = 'deprecated'
    subtypeSpec = Unsigned32.subtypeSpec + ValueRangeConstraint(0, 999)

class CItpSpLinkCapacity(TextualConvention, Unsigned32):
    description = 'This textual convention defines the planned \n                 capacity of a SS7 link in bit per second. \n                 \n                 If the link type is serial or HSL the link capacity\n                 can be obtained from information in the IF-MIB. \n                 \n                 If the link type is sctp/ip a value of zero \n                 indicates that link utilization should not \n                 be calculated for this SS7 link.'
    status = 'deprecated'
    subtypeSpec = Unsigned32.subtypeSpec + ConstraintsUnion(ValueRangeConstraint(0, 0), ValueRangeConstraint(56000, 2147483647), )
class CItpSpLinkUtilizationState(TextualConvention, Integer32):
    description = "Link Utilization State as follows:\n            'unMonitored(0)'    - traffic for a specified direction \n                                  is not being monitored.\n            'underThreshold(1)' - traffic for a specified direction\n                on a link is below the specified threshold.\n                      \n            'overThreshold(2)'  - traffic for a specified direction \n                on a link is above to or exceeds the specified \n                threshold."
    status = 'deprecated'
    subtypeSpec = Integer32.subtypeSpec + ConstraintsUnion(SingleValueConstraint(0, 1, 2))
    namedValues = NamedValues(("unMonitored", 0), ("underThreshold", 1), ("overThreshold", 2))

